<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lnms</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> config:set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nfsen_subdirlayout</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # IMPORTANT: this NfSen stores flow files</span></span>
